 function selectFile(e:ChangeEvent<HTMLInputElement>){const f=e.target.files?.[0];e.target.value='';if(!f)return;if(!mediaMime(f).startsWith('image/')&&!['video/mp4','video/quicktime','video/webm'].includes(mediaMime(f))){setError('Choose a supported photo, MP4, MOV, or WebM video.');return}if(f.size>200*1024*1024){setError('File must be under 200 MB.');return}if(isVideoFile(f)&&galleryFiles.length){setError('Remove carousel photos before selecting a video.');return}galleryPreviews.forEach(URL.revokeObjectURL);setGalleryFiles([]);setGalleryPreviews([]);setMedia(f);setVideoTitle(isVideoFile(f)?'':'');setVideoDuration(null);if(preview)URL.revokeObjectURL(preview);setPreview(URL.createObjectURL(f))}
