 {tab==='Home'&&<><div className="welcome"><div><span className="eyebrow">YOUR DAILY DOSE OF CONNECTION</span><h1>Your daily dose of <em>vibes.</em></h1><p>Little moments, big feelings, all your people.</p></div><span className="spark">✳</span></div><div className="stories"><button onClick={()=>document.getElementById('create')?.scrollIntoView({behavior:'smooth'})}><span className="storycircle">{initial(profile?.display_name)}<i>+</i></span>Your story</button><button onClick={()=>setTab('Discover')}><span className="storycircle">✦</span>Find people</button></div><form className="composer" id="create" onSubmit={publish}><div className="compose-row"><span className="avatar">{profile?.avatar_url?<img src={profile.avatar_url} alt="" />:initial(profile?.display_name||user.email)}</span><textarea value={caption} onChange={e=>setCaption(e.target.value)} placeholder={createKind==='text'?'Write your text post…':'What’s on your mind, '+(profile?.display_name?.split(' ')[0]||'friend')+'?'} rows={2}/><button type="button" className="draft-save" onClick={()=>{window.localStorage.setItem('vibely-caption-draft',caption);setNotice('Caption draft saved on this device. Media files are not included in drafts yet.')}}>Save text draft</button></div>{(createKind==='short'||createKind==='video')&&<div className="video-details-before-upload"><label>Video title<input value={videoTitle} maxLength={120} onChange={e=>setVideoTitle(e.target.value)} placeholder="Add a title before choosing your video"/></label><label>Short video description<textarea value={videoDescription} maxLength={5000} onChange={e=>setVideoDescription(e.target.value)} placeholder="What is this video about? (optional)" rows={3}/><small>{videoDescription.length}/5000 characters</small></label><p>These details will be saved with your video when you publish.</p></div>}{uploadState&&<p className="upload-status" role="status">{uploadState}</p>}{(preview||galleryPreviews.length>0)&&<div className="preview">{galleryPreviews.length>0?<div className="carousel-preview">{galleryPreviews.map((src,i)=><img key={src} src={src} alt={'Carousel photo '+(i+1)}/>)}</div>:media&&isVideoFile(media)?<><video src={preview} controls playsInline onLoadedMetadata={e=>setVideoDuration(Number.isFinite(e.currentTarget.duration)?e.currentTarget.duration:null)}/><div className="media-file-details"><b>{media.name}</b><span>{(media.size/1048576).toFixed(1)} MB{videoDuration!==null?' · '+Math.floor(videoDuration/60)+'m '+Math.floor(videoDuration%60)+'s':''}</span><label>Video title<input value={videoTitle} maxLength={120} onChange={e=>setVideoTitle(e.target.value)} placeholder="Give your video a title"/></label><label>Short video description <textarea value={videoDescription} maxLength={5000} onChange={e=>setVideoDescription(e.target.value)} placeholder="Describe your video for viewers…" rows={3}/><small>{videoDescription.length}/5000 characters</small></label><small>Upload status: selected · not yet uploaded or published</small></div></>:<><img src={preview} alt="Preview"/><div className="media-file-details"><b>{media?.name}</b><span>{media?(media.size/1048576).toFixed(1)+' MB':''}</span></div></>}<button type="button" onClick={()=>{if(preview)URL.revokeObjectURL(preview);galleryPreviews.forEach(URL.revokeObjectURL);setMedia(null);setPreview('');setGalleryFiles([]);setGalleryPreviews([]);setVideoTitle('');setVideoDescription('');setVideoDuration(null)}}><X/></button></div>}<div className="compose-bottom"><div className="upload-options"><label className="upload"><ImageIcon size={18}/> Photo / video<input id="media-input" type="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/quicktime,video/webm" onChange={selectFile}/></label><label className="upload"><ImageIcon size={18}/> Photo carousel<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple onChange={selectGallery}/></label></div><button className="primary" disabled={busy}>{busy?<LoaderCircle className="spin"/>:<Send size={16}/>} Share moment</button></div></form><div className="sectionhead"><div><h2>Your feed</h2><p>A little inspiration from your community</p></div><span>✧ For you</span></div>{loading?<div className="empty">Loading your feed…</div>:posts.length===0?<div className="empty"><div className="flower">✿</div><h3>Your feed is a blank canvas.</h3><p>Share your first moment, or explore to find people to follow.</p><button className="primary" onClick={()=>setTab('Discover')}>Find your people →</button></div>:<div className="feed">{posts.map(p=><article className="post" key={p.id}><div className="posthead"><span className="avatar">{p.profiles?.avatar_url?<img src={p.profiles.avatar_url} alt="" />:initial(p.profiles?.display_name||p.profiles?.username)}</span><div><b>{p.profiles?.display_name||p.profiles?.username||'Vibely member'}{p.profiles?.is_verified&&<span title="Vibe.ly verified" aria-label="Verified account" style={{display:'inline-flex',alignItems:'center',justifyContent:'center',marginLeft:5,width:16,height:16,borderRadius:'50%',background:'linear-gradient(145deg,#e9d5ff 0%,#a855f7 32%,#7e22ce 68%,#581c87 100%)',color:'#fff',fontSize:11,fontWeight:900,verticalAlign:'middle',clipPath:'polygon(50% 0%,61% 8%,75% 4%,82% 17%,96% 25%,92% 39%,100% 50%,92% 61%,96% 75%,82% 82%,75% 96%,61% 92%,50% 100%,39% 92%,25% 96%,18% 82%,4% 75%,8% 61%,0% 50%,8% 39%,4% 25%,18% 17%,25% 4%,39% 8%)',boxShadow:'inset 0 1px 2px #fff9, inset 0 -2px 3px #3b0764aa, 0 1px 3px #581c87aa',textShadow:'0 1px 1px #3b0764',border:'1px solid #d8b4fe'}}>✓</span>}</b><small>@{p.profiles?.username||'member'} · {ago(p.created_at)}</small></div>{p.author_id!==user.id&&<><button className="followmini" onClick={()=>{const pp=p.profiles;if(pp)void follow(pp)}}>{following.includes(p.author_id)?'Following':'+ Follow'}</button><button className="followmini" onClick={()=>setReportTarget({postId:p.id,userId:p.author_id})} aria-label="Report post or account">Report</button></>}</div>{p.author_id===user.id&&<button type="button" className="delete-post" disabled={busy} onClick={()=>void deletePost(p)}>Delete post</button>}{p.caption&&<p className="caption">{p.caption}</p>}{p.media_url&&<div className={p.mediaItems&&p.mediaItems.length>1?'postmedia post-carousel':'postmedia'}>{p.media_type==='video'?<video src={p.media_url} controls playsInline preload="metadata"/>:(p.mediaItems&&p.mediaItems.length>1?p.mediaItems.map((item,i)=>{const asset=item.media_assets;const src=asset?supabase.storage.from(asset.bucket_id).getPublicUrl(asset.object_path).data.publicUrl:(i===0?p.media_url:null);return src?<img key={item.position} src={src} alt={'Post photo '+(i+1)} loading="lazy"/>:null}):<img src={p.media_url} alt="Post" loading="lazy"/>)}</div>}<div className="postactions"><button className={p.likes?.some(x=>x.user_id===user.id)?'liked':''} onClick={()=>void like(p)}><Heart size={19}/>{p.likes?.length||0}</button><button onClick={()=>setCommentPost(commentPost===p.id?'':p.id)}><MessageCircle size={19}/>{p.comments?.length||0}</button><span>Share some kindness ✨</span></div>{commentPost===p.id&&<div className="comments">{(p.comments||[]).map(c=><p key={c.id}><b>{c.profiles?.display_name||c.profiles?.username||'Member'}</b> {c.body}</p>)}<form onSubmit={addComment}><input value={comment} onChange={e=>setComment(e.target.value)} placeholder="Write a kind comment..."/><button><Send size={16}/></button></form></div>}</article>)}</div>}</>}
 {tab==='Create'&&<section className="creator-hub"><span className="eyebrow">MAKE SOMETHING WORTH SHARING</span><h1>Create on <em>Vibe.ly.</em></h1><p>Choose a format to get started. Uploading a file never publishes it until you press Share.</p><div className="creator-grid"><button onClick={()=>{setCreateKind('text');setTab('Home');setTimeout(()=>document.getElementById('create')?.scrollIntoView({behavior:'smooth'}),100)}}><span>✍️</span><b>Text post</b><small>Share a thought or moment</small></button><button onClick={()=>{setCreateKind('photo');setTab('Home');setTimeout(()=>document.getElementById('media-input')?.click(),150)}}><span>📷</span><b>Photo</b><small>Share one image</small></button><button onClick={()=>{setCreateKind('carousel');setTab('Home');setTimeout(()=>document.querySelector<HTMLInputElement>('input[type=file][multiple]')?.click(),150)}}><span>🖼️</span><b>Photo carousel</b><small>Up to 10 images</small></button><button onClick={()=>{setCreateKind('short');setTab('Home');setTimeout(()=>{const el=document.getElementById('media-input') as HTMLInputElement|null;if(el){el.accept='video/mp4,video/quicktime,video/webm';el.click()}},150)}}><span>🎬</span><b>Short video</b><small>Vertical videos in Vibes</small></button><button onClick={()=>{setCreateKind('video');setTab('Home');setTimeout(()=>{const el=document.getElementById('media-input') as HTMLInputElement|null;if(el){el.accept='video/mp4,video/quicktime,video/webm';el.click()}},150)}}><span>▶️</span><b>Longer video</b><small>Share a full video</small></button><button onClick={()=>setNotice('Stories are not enabled yet because the existing backend has no Story expiry or audience workflow. Your posts and videos are ready to publish instead.')}><span>✨</span><b>Story</b><small>Story publishing not enabled yet</small></button><button onClick={()=>{const draft=window.localStorage.getItem('vibely-caption-draft');if(draft!==null){setCaption(draft);setNotice('Saved text draft restored.');setTab('Home');setTimeout(()=>document.getElementById('create')?.scrollIntoView({behavior:'smooth'}),100)}else setNotice('No saved text draft yet. You can save the caption from the composer.')}}><span>📝</span><b>Continue a draft</b><small>Restore a saved caption</small></button></div><button className="primary" onClick={()=>{setTab('Home');setTimeout(()=>document.getElementById('create')?.scrollIntoView({behavior:'smooth'}),100)}}>Open post composer</button></section>}
 {tab==='Vibes'&&<section className="vibes-page"><div className="sectionhead"><div><span className="eyebrow">VIBE.LY VIDEOS</span><h2>Vibes</h2><p>Short and long videos from your community.</p></div></div>{posts.filter(p=>p.media_type==='video'&&p.media_url).length===0?<div className="empty"><div className="flower">▶</div><h3>No videos yet.</h3><p>Be the first to share a video with your community.</p><button className="primary" onClick={()=>setTab('Create')}>Upload a video</button></div>:<div className="vibes-feed">{posts.filter(p=>p.media_type==='video'&&p.media_url).map(p=><article className="vibe-card" key={p.id}><video className="vibe-player" data-post-id={p.id} src={p.media_url||undefined} autoPlay playsInline preload="metadata" onClick={e=>{const v=e.currentTarget;v.muted=!v.muted;if(v.paused)void v.play().catch(()=>{})}} onPlay={e=>{document.querySelectorAll<HTMLVideoElement>('.vibe-player').forEach(v=>{if(v!==e.currentTarget)v.pause()});void supabase.from('video_playback_events').insert({user_id:user.id,post_id:p.id,event_type:'start',event_key:p.id+':start:'+Math.floor(Date.now()/60000)}).then(()=>{})}} onEnded={()=>{void supabase.from('video_playback_events').insert({user_id:user.id,post_id:p.id,event_type:'complete',event_key:p.id+':complete:'+Math.floor(Date.now()/60000)}).then(()=>{})}}/><div className="vibe-overlay"><button type="button" className="vibe-creator" onClick={()=>void recordProfileVisit(p.author_id)}>{p.profiles?.display_name||p.profiles?.username||'Vibely creator'}</button><p>{p.mediaItems?.[0]?.media_assets?.video_metadata?.title||p.caption||'A moment shared on Vibe.ly'}</p><button type="button" onClick={e=>{e.stopPropagation();const video=e.currentTarget.closest('.vibe-card')?.querySelector('video');if(video){video.muted=!video.muted;if(!video.muted)void video.play().catch(()=>{})}}}>{'🔊'} Sound</button><button onClick={()=>void like(p)}><Heart size={18}/> {p.likes?.length||0}</button><button onClick={()=>setCommentPost(commentPost===p.id?'':p.id)}><MessageCircle size={18}/> {p.comments?.length||0}</button></div>{commentPost===p.id&&<div className="comments">{(p.comments||[]).map(c=><p key={c.id}><b>{c.profiles?.display_name||c.profiles?.username||'Member'}</b> {c.body}</p>)}<form onSubmit={addComment}><input value={comment} onChange={e=>setComment(e.target.value)} placeholder="Write a kind comment..."/><button><Send size={16}/></button></form></div>}</article>)}</div>}</section>}
